//
//  True Particle System with Compute Shader
//  Native Metal Shader - Advanced Effects
//

#include <metal_stdlib>
using namespace metal;

// MARK: - Structures

struct Particle {
    float2 position;
    float2 velocity;
    float life;
    float size;
    float4 color;
};

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float particle_count;
    float particle_speed;
    float particle_size;
    float gravity;
};

// MARK: - Compute Shader (Particle Simulation)

kernel void particle_simulation(
    device Particle *particles [[buffer(0)]],
    constant Uniforms &uniforms [[buffer(1)]],
    uint id [[thread_position_in_grid]]
)
{
    uint particle_count = uint(uniforms.particle_count * 1000.0);

    if (id >= particle_count) return;

    Particle particle = particles[id];

    // Update particle
    float dt = 1.0 / 60.0; // Assume 60 FPS

    // Apply velocity
    particle.position += particle.velocity * dt * uniforms.particle_speed;

    // Apply gravity
    particle.velocity.y += uniforms.gravity * dt;

    // Decrease life
    particle.life -= dt;

    // Reset particle if dead
    if (particle.life <= 0.0) {
        // Pseudo-random based on particle ID and frame count
        float seed = float(id) + float(uniforms.FrameCount) * 0.1;
        float rand_x = fract(sin(seed * 12.9898) * 43758.5453);
        float rand_y = fract(sin(seed * 78.233) * 43758.5453);
        float rand_vx = fract(sin(seed * 45.164) * 43758.5453);
        float rand_vy = fract(sin(seed * 94.673) * 43758.5453);

        particle.position = float2(rand_x, 0.1); // Start at bottom
        particle.velocity = float2((rand_vx - 0.5) * 2.0, rand_vy * 2.0 + 1.0);
        particle.life = 3.0 + rand_y * 2.0;
        particle.size = uniforms.particle_size * (0.5 + rand_x * 0.5);

        // Random color
        particle.color = float4(
            0.5 + rand_x * 0.5,
            0.5 + rand_y * 0.5,
            0.5 + rand_vx * 0.5,
            1.0
        );
    }

    // Wrap around screen
    if (particle.position.x < 0.0) particle.position.x += 1.0;
    if (particle.position.x > 1.0) particle.position.x -= 1.0;
    if (particle.position.y > 1.0) particle.position.y = 0.0;

    particles[id] = particle;
}

// MARK: - Vertex Shader

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// MARK: - Fragment Shader

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    device Particle *particles [[buffer(0)]],
    constant Uniforms &uniforms [[buffer(1)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    // Sample original image
    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    // Render particles
    uint particle_count = uint(uniforms.particle_count * 1000.0);

    for (uint i = 0; i < particle_count; i++) {
        Particle particle = particles[i];

        // Distance to particle
        float2 toParticle = in.texCoord - particle.position;
        toParticle.x *= uniforms.OutputSize.x / uniforms.OutputSize.y; // Aspect ratio correction
        float dist = length(toParticle);

        // Particle rendering
        float particleRadius = particle.size * 0.01;
        float alpha = smoothstep(particleRadius, particleRadius * 0.5, dist);
        alpha *= particle.life / 5.0; // Fade based on life

        // Blend particle color
        color = mix(color, particle.color, alpha * particle.color.a);
    }

    return color;
}

